// region Serialization

/**
 * Signal that the JSON serialization could not be performed.
 *
 * The {@link SerializationError.path} points into the instance which was to be
 * serialized, and *not* into a JSON document -- at the point of the failure,
 * there is no document yet. For example, `.submodels[0].value` tells you that
 * the serialization broke on `that.submodels[0].value`.
 *
 * Mind that this path is a plain string, unlike the structured
 * {@link Path} of the de-serialization. A segment of the latter carries
 * the JSON value it was read from, and while serializing there is no such
 * value to carry.
 */
export class SerializationError extends Error {
  private readonly _segments = new Array<string>();

  /**
   * Render the path to the erroneous value as a TypeScript access expression.
   */
  get path(): string {
    return this._segments.join("");
  }

  /**
   * Insert the access to the property `name` before the {@link path}.
   */
  prependProperty(name: string): void {
    this._segments.unshift(`.${name}`);
  }

  /**
   * Insert the access to the item at `index` before the {@link path}.
   */
  prependIndex(index: number): void {
    this._segments.unshift(`[${index}]`);
  }
}

/**
 * Serialize `that` integer to a JSON-able value.
 *
 * Only the integers in the range [-2^53 + 1, 2^53 - 1] are serialized. Outside
 * of it, an integer can not be exactly represented as a 64-bit floating-point
 * number, which is what the JSON de-serializers of the other languages read
 * a number into.
 *
 * @param that - integer to be serialized
 * @returns `that`, unchanged
 * @throws {@link SerializationError} if outside the range
 */
function integerToJsonable(that: number): number {
  if (!Number.isFinite(that) || that < -9007199254740991 || that > 9007199254740991) {
    throw new SerializationError(
      `The integer can not be serialized to JSON as it is outside ` +
        `the range [-2^53 + 1, 2^53 - 1]: ${that}`
    );
  }
  return that;
}

/**
 * Serialize every item of `items` with `serializeItem` into a JSON-able
 * array.
 *
 * @param items - to be serialized
 * @param serializeItem - to serialize a single item of `items`
 * @returns JSON-able array
 * @typeParam T - type of a single item to be serialized
 * @typeParam J - type of a single item once serialized
 */
/**
 * Serialize `items` one by one, recording the index of the one which is refused.
 */
function serializeArray<T, J extends JsonValue>(
  items: Iterable<T>,
  serializeItem: (item: T) => J
): Array<J> {
  const result = new Array<J>();
  let i = 0;
  for (const item of items) {
    try {
      result.push(serializeItem(item));
    } catch (error) {
      if (error instanceof SerializationError) {
        error.prependIndex(i);
      }
      throw error;
    }
    i++;
  }
  return result;
}

/**
 * Transform the instance to its JSON-able representation.
 */
class Serializer extends AasTypes.AbstractTransformer<JsonObject> {


  /**
   * Serialize `that` to a JSON-able representation.
   *
   * @param that - instance to be serialization
   * @returns JSON-able representation
   */
  transformBranch(
    that: AasTypes.Branch
  ): JsonObject {
    const jsonable: JsonObject = {};

    jsonable["identifier"] =
      that.identifier;

    jsonable["description"] =
      that.description;

    jsonable["modelType"] = "Branch";

    return jsonable;
  }

  /**
   * Serialize `that` to a JSON-able representation.
   *
   * @param that - instance to be serialization
   * @returns JSON-able representation
   */
  transformLeaf(
    that: AasTypes.Leaf
  ): JsonObject {
    const jsonable: JsonObject = {};

    jsonable["identifier"] =
      that.identifier;

    jsonable["description"] =
      that.description;

    try {
      jsonable["value"] =
        integerToJsonable(that.value);
    } catch (error) {
      if (error instanceof SerializationError) {
        error.prependProperty("value");
      }
      throw error;
    }

    jsonable["modelType"] = "Leaf";

    return jsonable;
  }

  /**
   * Serialize `that` to a JSON-able representation.
   *
   * @param that - instance to be serialization
   * @returns JSON-able representation
   */
  transformBlossom(
    that: AasTypes.Blossom
  ): JsonObject {
    const jsonable: JsonObject = {};

    jsonable["identifier"] =
      that.identifier;

    jsonable["description"] =
      that.description;

    try {
      jsonable["value"] =
        integerToJsonable(that.value);
    } catch (error) {
      if (error instanceof SerializationError) {
        error.prependProperty("value");
      }
      throw error;
    }

    jsonable["details"] =
      that.details;

    jsonable["modelType"] = "Blossom";

    return jsonable;
  }

  /**
   * Serialize `that` to a JSON-able representation.
   *
   * @param that - instance to be serialization
   * @returns JSON-able representation
   */
  transformSomething(
    that: AasTypes.Something
  ): JsonObject {
    const jsonable: JsonObject = {};

    try {
      jsonable["someChoice"] =
        this.transform(that.someChoice);
    } catch (error) {
      if (error instanceof SerializationError) {
        error.prependProperty("someChoice");
      }
      throw error;
    }

    try {
      jsonable["somethingWithoutChoice"] =
        this.transform(that.somethingWithoutChoice);
    } catch (error) {
      if (error instanceof SerializationError) {
        error.prependProperty("somethingWithoutChoice");
      }
      throw error;
    }

    return jsonable;
  }

  /**
   * Serialize `that` to a JSON-able representation.
   *
   * @param that - instance to be serialization
   * @returns JSON-able representation
   */
  transformContainer(
    that: AasTypes.Container
  ): JsonObject {
    const jsonable: JsonObject = {};

    try {
      jsonable["node"] =
        this.transform(that.node);
    } catch (error) {
      if (error instanceof SerializationError) {
        error.prependProperty("node");
      }
      throw error;
    }

    try {
      jsonable["something"] =
        this.transform(that.something);
    } catch (error) {
      if (error instanceof SerializationError) {
        error.prependProperty("something");
      }
      throw error;
    }

    return jsonable;
  }
}

const SERIALIZER = new Serializer();

/**
 * Convert `that` to a JSON-able structure.
 *
 * @param that - AAS data to be recursively converted to a JSON-able structure
 * @returns
 * JSON-able structure which can be further processed with, say,
 * {@link https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/JSON/stringify|JSON.stringify})
 */
export function toJsonable(that: AasTypes.Class): JsonObject {
  return SERIALIZER.transform(that);
}

